CREATE OR REPLACE FUNCTION private.team_directory_rows()
 RETURNS TABLE(profile_id uuid, member_id uuid, full_name text, profile_image_path text, team_bio text, primary_locale text, linkedin_url text, contact_email text, public_coach_profile_id uuid, translations jsonb, assignments jsonb, primary_sort_order integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
  SELECT p.id AS profile_id,
         m.id AS member_id,
         m.full_name,
         p.profile_image_path,
         p.team_bio,
         p.primary_locale,
         p.linkedin_url,
         private.team_contact_email(p.id) AS contact_email,
         CASE
           WHEN p.visibility = 'published'::member_visibility
                AND public.member_is_active(m.activity_state)
                AND public.member_has_directory_credential(m.credential_slug, m.credential_expires_on)
           THEN p.id
           ELSE NULL::uuid
         END AS public_coach_profile_id,
         COALESCE((
           SELECT jsonb_object_agg(t.locale, jsonb_build_object('team_bio', t.team_bio))
           FROM public.member_profile_translations t
           WHERE t.profile_id = p.id AND t.is_ready
         ), '{}'::jsonb) AS translations,
         COALESCE((
           SELECT jsonb_agg(jsonb_build_object(
             'project_slug', pr.slug,
             'project_name', pr.name,
             'project_name_de', pr.name_de,
             'project_name_fr', pr.name_fr,
             'project_name_it', pr.name_it,
             'project_sort_order', pr.sort_order,
             'role_name', rl.name,
             'role_name_de', rl.name_de,
             'role_name_fr', rl.name_fr,
             'role_name_it', rl.name_it,
             'sort_order', a.sort_order
           ) ORDER BY a.sort_order, pr.sort_order)
           FROM public.op_assignments a
           JOIN public.op_projects pr ON pr.id = a.project_id AND pr.is_active
           JOIN public.op_project_roles rl ON rl.id = a.role_id
           WHERE a.member_id = m.id
         ), '[]'::jsonb) AS assignments,
         COALESCE((
           SELECT min(a.sort_order)
           FROM public.op_assignments a
           JOIN public.op_projects pr ON pr.id = a.project_id AND pr.is_active
           WHERE a.member_id = m.id
         ), 0) AS primary_sort_order
  FROM public.member_directory_profiles p
  JOIN public.members m ON m.id = p.member_id
  WHERE public.member_is_active(m.activity_state)
    AND EXISTS (
      SELECT 1
      FROM public.op_assignments a
      JOIN public.op_projects pr ON pr.id = a.project_id AND pr.is_active
      WHERE a.member_id = m.id
    );
$function$
;

CREATE OR REPLACE FUNCTION public.apply_attendance_import(_import_id uuid, _actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  imp public.event_attendance_imports%ROWTYPE;
  row_rec record;
  reg public.event_registrations%ROWTYPE;
  checked_in int := 0;
  already int := 0;
  skipped int := 0;
BEGIN
  IF _actor IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  SELECT * INTO imp FROM public.event_attendance_imports
    WHERE id = _import_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('outcome', 'not_found');
  END IF;

  IF NOT private.event_is_managed_by(imp.event_id, _actor) THEN
    RAISE EXCEPTION 'not authorised for this event';
  END IF;

  IF imp.status = 'discarded' THEN
    RETURN jsonb_build_object('outcome', 'discarded');
  END IF;

  -- Re-applying is a no-op that answers with the recorded result.
  IF imp.status = 'applied' THEN
    RETURN jsonb_build_object('outcome', 'applied') || coalesce(imp.stats, '{}'::jsonb);
  END IF;

  FOR row_rec IN
    SELECT * FROM public.event_attendance_import_rows
     WHERE import_id = imp.id
       AND apply_decision = 'check_in'
       AND match_registration_id IS NOT NULL
  LOOP
    SELECT * INTO reg FROM public.event_registrations
      WHERE id = row_rec.match_registration_id FOR UPDATE;

    IF NOT FOUND OR reg.event_id <> imp.event_id THEN
      skipped := skipped + 1;
      CONTINUE;
    END IF;

    -- Preview is never trusted: eligibility is decided here, at write time.
    IF private.registration_is_check_in_eligible(reg) IS NOT NULL THEN
      skipped := skipped + 1;
      CONTINUE;
    END IF;

    IF reg.checked_in_at IS NOT NULL THEN
      already := already + 1;
      CONTINUE;
    END IF;

    UPDATE public.event_registrations
       SET checked_in_at = now(),
           checked_in_by = _actor,
           checked_in_source = 'import'
     WHERE id = reg.id AND checked_in_at IS NULL;

    UPDATE public.guest_passes
       SET status = 'attended'
     WHERE registration_id = reg.id
       AND status IN ('approved', 'registered');

    checked_in := checked_in + 1;
  END LOOP;

  UPDATE public.event_attendance_imports
     SET status = 'applied',
         stats = coalesce(stats, '{}'::jsonb) || jsonb_build_object(
           'checked_in', checked_in,
           'already', already,
           'skipped', skipped
         )
   WHERE id = imp.id;

  RETURN jsonb_build_object(
    'outcome', 'applied',
    'checked_in', checked_in,
    'already', already,
    'skipped', skipped
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.attendance_session_status(_session_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  s public.event_attendance_sessions%ROWTYPE;
  e public.events%ROWTYPE;
BEGIN
  IF _session_token !~ '^[A-Za-z0-9_-]{16,64}$' THEN
    RETURN NULL;
  END IF;
  SELECT * INTO s FROM public.event_attendance_sessions WHERE public_token = _session_token;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  SELECT * INTO e FROM public.events WHERE id = s.event_id;
  RETURN jsonb_build_object(
    'open', s.closed_at IS NULL AND now() <= s.ends_at,
    'ends_at', s.ends_at,
    'event_title', coalesce(e.title, ''),
    'event_slug', e.slug
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.check_in_registration(_registration_id uuid, _actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r public.event_registrations%ROWTYPE;
  uid uuid := _actor;
  ineligible text;
BEGIN
  IF uid IS NULL THEN
    RAISE EXCEPTION 'authentication required';
  END IF;

  SELECT * INTO r FROM public.event_registrations
    WHERE id = _registration_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('outcome', 'not_found');
  END IF;

  IF NOT private.event_is_managed_by(r.event_id, uid) THEN
    RAISE EXCEPTION 'not authorised for this event';
  END IF;

  ineligible := private.registration_is_check_in_eligible(r);
  IF ineligible IS NOT NULL THEN
    RETURN jsonb_build_object('outcome', 'ineligible', 'reason', ineligible);
  END IF;

  IF r.checked_in_at IS NOT NULL THEN
    RETURN jsonb_build_object(
      'outcome', 'already',
      'checked_in_at', r.checked_in_at,
      'checked_in_by', r.checked_in_by
    );
  END IF;

  UPDATE public.event_registrations
     SET checked_in_at = now(),
         checked_in_by = uid,
         checked_in_source = 'door'
   WHERE id = r.id AND checked_in_at IS NULL;

  -- A comped guest-pass seat records the attendance on the pass as well, so
  -- Membership & Engagement can see who actually came.
  UPDATE public.guest_passes
     SET status = 'attended'
   WHERE registration_id = r.id
     AND status IN ('approved', 'registered');

  RETURN jsonb_build_object('outcome', 'checked_in', 'checked_in_at', now());
END;
$function$
;

CREATE OR REPLACE FUNCTION public.close_event_attendance_session(_event_id uuid, _actor uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  uid uuid := coalesce(auth.uid(), _actor);
BEGIN
  IF uid IS NULL OR NOT private.event_is_managed_by(_event_id, uid) THEN
    RAISE EXCEPTION 'not authorised for this event';
  END IF;
  UPDATE public.event_attendance_sessions
     SET closed_at = now(), closed_by = uid
   WHERE event_id = _event_id AND closed_at IS NULL;
  RETURN jsonb_build_object('outcome', 'closed');
END;
$function$
;

CREATE OR REPLACE FUNCTION public.directory_allows_non_credentialed()
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT coalesce((SELECT c.allow_non_credentialed FROM public.coach_finder_config c LIMIT 1), false)
$function$
;

CREATE OR REPLACE FUNCTION public.get_certificate_by_token(_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  c public.event_certificates%ROWTYPE;
BEGIN
  IF _token !~ '^[A-Za-z0-9_-]{16,64}$' THEN
    RETURN NULL;
  END IF;
  SELECT * INTO c FROM public.event_certificates WHERE public_token = _token;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  IF c.status = 'revoked' THEN
    RETURN jsonb_build_object('status', 'revoked', 'serial', c.serial, 'locale', c.locale);
  END IF;

  RETURN jsonb_build_object(
    'status', 'issued',
    'serial', c.serial,
    'locale', c.locale,
    'holder_name', c.holder_name,
    'event_title', c.event_title_snapshot,
    'completed_on', c.completed_on,
    'cc_hours', c.cc_hours,
    'rd_hours', c.rd_hours,
    'issued_at', c.issued_at
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_event_attendance_session(_event_id uuid, _actor uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  uid uuid := coalesce(auth.uid(), _actor);
  s public.event_attendance_sessions%ROWTYPE;
BEGIN
  IF uid IS NULL OR NOT private.event_is_managed_by(_event_id, uid) THEN
    RAISE EXCEPTION 'not authorised for this event';
  END IF;
  SELECT * INTO s FROM public.event_attendance_sessions
    WHERE event_id = _event_id AND closed_at IS NULL AND now() <= ends_at
    ORDER BY started_at DESC LIMIT 1;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  RETURN jsonb_build_object(
    'id', s.id, 'public_token', s.public_token,
    'ends_at', s.ends_at, 'grace_minutes', s.grace_minutes
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  full_name text := COALESCE(
    NEW.raw_user_meta_data ->> 'full_name',
    NEW.raw_user_meta_data ->> 'name',
    ''
  );
BEGIN
  INSERT INTO public.profiles (id, first_name, last_name)
  VALUES (
    NEW.id,
    COALESCE(
      NULLIF(NEW.raw_user_meta_data ->> 'first_name', ''),
      NULLIF(split_part(full_name, ' ', 1), ''),
      ''
    ),
    COALESCE(
      NULLIF(NEW.raw_user_meta_data ->> 'last_name', ''),
      NULLIF(substr(full_name, NULLIF(strpos(full_name, ' '), 0) + 1), ''),
      ''
    )
  )
  ON CONFLICT (id) DO NOTHING;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.issue_event_completion(_event_id uuid, _actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
DECLARE
  ev public.events%ROWTYPE;
  reg public.event_registrations%ROWTYPE;
  cc numeric;
  rd numeric;
  grantable boolean := false;
  cert_id uuid;
  mid uuid;
  issued int := 0;
  awards int := 0;
  skipped_already int := 0;
  skipped_ineligible int := 0;
BEGIN
  -- A signed-in caller is always themselves; only the trusted server path may
  -- name a different actor.
  IF auth.uid() IS NOT NULL THEN
    _actor := auth.uid();
  END IF;

  IF _actor IS NULL OR NOT private.event_is_managed_by(_event_id, _actor) THEN
    RAISE EXCEPTION 'not authorised for this event';
  END IF;

  SELECT * INTO ev FROM public.events WHERE id = _event_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'event not found';
  END IF;
  IF NOT ev.certificates_enabled THEN
    RAISE EXCEPTION 'certificates are not enabled for this event';
  END IF;

  SELECT g.cc, g.rd INTO cc, rd FROM private.event_grantable_hours(_event_id) g;
  grantable := cc IS NOT NULL;

  FOR reg IN
    SELECT * FROM public.event_registrations
     WHERE event_id = _event_id
       AND status = 'confirmed'
       AND checked_in_at IS NOT NULL
     ORDER BY checked_in_at
  LOOP
    IF private.registration_is_check_in_eligible(reg) IS NOT NULL THEN
      skipped_ineligible := skipped_ineligible + 1;
      CONTINUE;
    END IF;

    IF EXISTS (
      SELECT 1 FROM public.event_certificates c
       WHERE c.registration_id = reg.id AND c.status = 'issued'
    ) THEN
      skipped_already := skipped_already + 1;
      CONTINUE;
    END IF;

    mid := NULL;
    IF reg.user_id IS NOT NULL THEN
      SELECT m.id INTO mid FROM public.members m WHERE m.auth_user_id = reg.user_id LIMIT 1;
    END IF;

    INSERT INTO public.event_certificates (
      registration_id, event_id, member_id, serial, public_token, locale,
      holder_name, event_title_snapshot, completed_on, cc_hours, rd_hours, issued_by
    ) VALUES (
      reg.id, _event_id, mid,
      private.next_certificate_serial(),
      private.new_certificate_token(),
      coalesce(reg.locale, 'en'),
      reg.full_name,
      ev.title,
      (ev.starts_at AT TIME ZONE coalesce(ev.timezone, 'Europe/Zurich'))::date,
      CASE WHEN grantable THEN cc ELSE NULL END,
      CASE WHEN grantable THEN rd ELSE NULL END,
      _actor
    )
    RETURNING id INTO cert_id;

    issued := issued + 1;

    IF grantable AND (coalesce(cc, 0) + coalesce(rd, 0)) > 0 THEN
      INSERT INTO public.event_cce_awards (
        event_id, registration_id, member_id, certificate_id,
        cc_hours, rd_hours, status, awarded_by
      ) VALUES (
        _event_id, reg.id, mid, cert_id, coalesce(cc, 0), coalesce(rd, 0), 'awarded', _actor
      )
      ON CONFLICT (registration_id) DO UPDATE SET
        status = 'awarded',
        cc_hours = EXCLUDED.cc_hours,
        rd_hours = EXCLUDED.rd_hours,
        certificate_id = EXCLUDED.certificate_id,
        member_id = EXCLUDED.member_id,
        awarded_at = now(),
        awarded_by = EXCLUDED.awarded_by,
        revoked_at = NULL,
        revoked_by = NULL;
      awards := awards + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'certificates_issued', issued,
    'awards_written', awards,
    'skipped_already', skipped_already,
    'skipped_ineligible', skipped_ineligible
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.live_chat_online_count()
 RETURNS integer
