CREATE OR REPLACE FUNCTION public.member_has_directory_credential(_credential_slug text, _credential_expires_on date)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT upper(coalesce(_credential_slug, '')) IN ('ACC', 'PCC', 'MCC')
     AND (_credential_expires_on IS NULL OR _credential_expires_on >= current_date)
$function$
;

CREATE OR REPLACE FUNCTION public.member_is_active(_activity_state member_activity_state)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT _activity_state = 'active'
$function$
;

CREATE OR REPLACE FUNCTION public.member_is_directory_eligible(_member_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT (
      public.member_is_active(m.activity_state)
      OR (public.directory_allows_non_credentialed() AND m.activity_state = 'grace')
    )
    AND (
      public.member_has_directory_credential(m.credential_slug, m.credential_expires_on)
      OR public.directory_allows_non_credentialed()
    )
  FROM public.members m
  WHERE m.id = _member_id
$function$
;

CREATE OR REPLACE FUNCTION public.open_event_attendance_session(_event_id uuid, _grace_minutes integer DEFAULT 30, _actor uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  uid uuid := coalesce(auth.uid(), _actor);
  s public.event_attendance_sessions%ROWTYPE;
  ev public.events%ROWTYPE;
  grace int := least(greatest(coalesce(_grace_minutes, 30), 0), 180);
  token text;
BEGIN
  IF uid IS NULL OR NOT private.event_is_managed_by(_event_id, uid) THEN
    RAISE EXCEPTION 'not authorised for this event';
  END IF;

  SELECT * INTO s FROM public.event_attendance_sessions
    WHERE event_id = _event_id AND closed_at IS NULL
    ORDER BY started_at DESC LIMIT 1;

  IF FOUND AND now() <= s.ends_at THEN
    RETURN jsonb_build_object(
      'id', s.id, 'public_token', s.public_token,
      'ends_at', s.ends_at, 'grace_minutes', s.grace_minutes
    );
  END IF;

  IF FOUND THEN
    UPDATE public.event_attendance_sessions
       SET closed_at = now(), closed_by = uid
     WHERE id = s.id;
  END IF;

  SELECT * INTO ev FROM public.events WHERE id = _event_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'event not found';
  END IF;

  token := translate(encode(extensions.gen_random_bytes(24), 'base64'), '+/=', '-_');

  INSERT INTO public.event_attendance_sessions
    (event_id, public_token, ends_at, grace_minutes, started_by)
  VALUES (
    _event_id,
    token,
    greatest(coalesce(ev.ends_at, ev.starts_at), now()) + make_interval(mins => grace),
    grace,
    uid
  )
  RETURNING * INTO s;

  RETURN jsonb_build_object(
    'id', s.id, 'public_token', s.public_token,
    'ends_at', s.ends_at, 'grace_minutes', s.grace_minutes
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.reissue_event_certificate(_certificate_id uuid, _actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
DECLARE
  c public.event_certificates%ROWTYPE;
  reg public.event_registrations%ROWTYPE;
  ev public.events%ROWTYPE;
  cc numeric;
  rd numeric;
  grantable boolean := false;
  new_id uuid;
  new_token text;
  mid uuid;
BEGIN
  IF auth.uid() IS NOT NULL THEN
    _actor := auth.uid();
  END IF;

  SELECT * INTO c FROM public.event_certificates WHERE id = _certificate_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('outcome', 'not_found');
  END IF;
  IF _actor IS NULL OR NOT private.event_is_managed_by(c.event_id, _actor) THEN
    RAISE EXCEPTION 'not authorised for this event';
  END IF;

  SELECT * INTO reg FROM public.event_registrations WHERE id = c.registration_id FOR UPDATE;
  IF NOT FOUND OR reg.checked_in_at IS NULL
     OR private.registration_is_check_in_eligible(reg) IS NOT NULL THEN
    RETURN jsonb_build_object('outcome', 'ineligible');
  END IF;

  SELECT * INTO ev FROM public.events WHERE id = c.event_id;
  SELECT g.cc, g.rd INTO cc, rd FROM private.event_grantable_hours(c.event_id) g;
  grantable := cc IS NOT NULL;

  UPDATE public.event_certificates
     SET status = 'revoked', revoked_at = now(), revoked_by = _actor,
         revoke_reason = coalesce(revoke_reason, 'reissued')
   WHERE id = c.id AND status = 'issued';

  mid := NULL;
  IF reg.user_id IS NOT NULL THEN
    SELECT m.id INTO mid FROM public.members m WHERE m.auth_user_id = reg.user_id LIMIT 1;
  END IF;

  new_token := private.new_certificate_token();

  INSERT INTO public.event_certificates (
    registration_id, event_id, member_id, serial, public_token, locale,
    holder_name, event_title_snapshot, completed_on, cc_hours, rd_hours, issued_by
  ) VALUES (
    reg.id, c.event_id, mid,
    private.next_certificate_serial(),
    new_token,
    coalesce(reg.locale, c.locale),
    reg.full_name,
    ev.title,
    (ev.starts_at AT TIME ZONE coalesce(ev.timezone, 'Europe/Zurich'))::date,
    CASE WHEN grantable THEN cc ELSE NULL END,
    CASE WHEN grantable THEN rd ELSE NULL END,
    _actor
  )
  RETURNING id INTO new_id;

  UPDATE public.event_certificates SET superseded_by = new_id WHERE id = c.id;

  IF grantable AND (coalesce(cc, 0) + coalesce(rd, 0)) > 0 THEN
    INSERT INTO public.event_cce_awards (
      event_id, registration_id, member_id, certificate_id,
      cc_hours, rd_hours, status, awarded_by
    ) VALUES (
      c.event_id, reg.id, mid, new_id, coalesce(cc, 0), coalesce(rd, 0), 'awarded', _actor
    )
    ON CONFLICT (registration_id) DO UPDATE SET
      status = 'awarded',
      cc_hours = EXCLUDED.cc_hours,
      rd_hours = EXCLUDED.rd_hours,
      certificate_id = EXCLUDED.certificate_id,
      member_id = EXCLUDED.member_id,
      awarded_at = now(),
      awarded_by = EXCLUDED.awarded_by,
      revoked_at = NULL,
      revoked_by = NULL;
  END IF;

  RETURN jsonb_build_object('outcome', 'reissued', 'certificate_id', new_id, 'token', new_token);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.revoke_event_certificate(_certificate_id uuid, _actor uuid, _reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
DECLARE
  c public.event_certificates%ROWTYPE;
BEGIN
  IF auth.uid() IS NOT NULL THEN
    _actor := auth.uid();
  END IF;

  SELECT * INTO c FROM public.event_certificates WHERE id = _certificate_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('outcome', 'not_found');
  END IF;
  IF _actor IS NULL OR NOT private.event_is_managed_by(c.event_id, _actor) THEN
    RAISE EXCEPTION 'not authorised for this event';
  END IF;
  IF c.status = 'revoked' THEN
    RETURN jsonb_build_object('outcome', 'already_revoked');
  END IF;

  UPDATE public.event_certificates
     SET status = 'revoked', revoked_at = now(), revoked_by = _actor,
         revoke_reason = _reason
   WHERE id = c.id;

  UPDATE public.event_cce_awards
     SET status = 'revoked', revoked_at = now(), revoked_by = _actor
   WHERE certificate_id = c.id AND status = 'awarded';

  RETURN jsonb_build_object('outcome', 'revoked', 'registration_id', c.registration_id);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.self_check_in_with_ticket(_session_token text, _ticket_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  s public.event_attendance_sessions%ROWTYPE;
  r public.event_registrations%ROWTYPE;
  ineligible text;
BEGIN
  -- Both halves must look like a token before anything is read, and a bad
  -- session and a bad ticket answer identically so the pair is not an oracle.
  IF _session_token !~ '^[A-Za-z0-9_-]{16,64}$'
     OR _ticket_token !~ '^[A-Za-z0-9_-]{16,64}$' THEN
    RETURN jsonb_build_object('outcome', 'not_found');
  END IF;

  SELECT * INTO s FROM public.event_attendance_sessions
    WHERE public_token = _session_token FOR SHARE;
  IF NOT FOUND OR s.closed_at IS NOT NULL OR now() > s.ends_at THEN
    RETURN jsonb_build_object('outcome', 'window_closed');
  END IF;

  SELECT * INTO r FROM public.event_registrations
    WHERE check_in_token = _ticket_token FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('outcome', 'not_found');
  END IF;

  IF r.event_id <> s.event_id THEN
    RETURN jsonb_build_object('outcome', 'wrong_event');
  END IF;

  ineligible := private.registration_is_check_in_eligible(r);
  IF ineligible IS NOT NULL THEN
    RETURN jsonb_build_object('outcome', 'ineligible', 'reason', ineligible, 'name', r.full_name);
  END IF;

  IF r.checked_in_at IS NOT NULL THEN
    RETURN jsonb_build_object(
      'outcome', 'already',
      'checked_in_at', r.checked_in_at,
      'name', r.full_name
    );
  END IF;

  UPDATE public.event_registrations
     SET checked_in_at = now(),
         checked_in_by = NULL,
         checked_in_source = 'self_qr',
         checked_in_session_id = s.id
   WHERE id = r.id AND checked_in_at IS NULL;

  UPDATE public.guest_passes
     SET status = 'attended'
   WHERE registration_id = r.id
     AND status IN ('approved', 'registered');

  RETURN jsonb_build_object('outcome', 'checked_in', 'name', r.full_name);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.tg_articles_content_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.title IS DISTINCT FROM OLD.title
     OR NEW.excerpt IS DISTINCT FROM OLD.excerpt
     OR NEW.content IS DISTINCT FROM OLD.content THEN
    NEW.content_updated_at = now();
  END IF;
  RETURN NEW;
END; $function$
;

CREATE OR REPLACE FUNCTION public.tg_articles_publish_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  uid uuid := auth.uid();
  is_admin boolean := private.has_role(auth.uid(), 'admin');
BEGIN
  IF NEW.status IN ('published', 'scheduled')
     AND NEW.status IS DISTINCT FROM OLD.status THEN
    IF NOT is_admin AND NOT private.is_article_publisher(uid) THEN
      RAISE EXCEPTION 'only a Communication & Marketing publisher may publish an article';
    END IF;
    IF NOT is_admin AND NEW.created_by IS NOT NULL AND NEW.created_by = uid THEN
      RAISE EXCEPTION 'the creator of an article cannot publish it; another publisher must review it';
    END IF;
    -- The releaser is derived from the session, never trusted from the client.
    NEW.published_by := coalesce(uid, OLD.published_by);
  ELSE
    NEW.published_by := OLD.published_by;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.tg_articles_single_featured()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.is_featured THEN
    UPDATE public.articles
      SET is_featured = false
      WHERE is_featured = true
        AND id <> NEW.id;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.tg_articles_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$
;

