         cadence_note_it = NEW.name_it
   WHERE cadence_slug = NEW.slug;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.tg_directory_profile_eligibility_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.visibility = 'published'
     AND NOT coalesce(public.member_is_directory_eligible(NEW.member_id), false) THEN
    RAISE EXCEPTION 'member % is not directory-eligible under the current Coach Finder rules (active membership required; a valid ACC, PCC or MCC credential unless non-credentialed listings are enabled)', NEW.member_id;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.tg_event_cce_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  uid uuid := auth.uid();
  trusted boolean := coalesce(auth.role(), current_user) = 'service_role';
  approver boolean := uid IS NOT NULL AND private.is_editor(uid);
  approver_states public.event_cce_status[] :=
    ARRAY['submitted', 'approved', 'declined']::public.event_cce_status[];
BEGIN
  NEW.updated_at = now();

  -- Only an editor/admin may move an application into an official state, or
  -- change the recorded submission and decision facts.
  IF NOT trusted AND NOT approver THEN
    IF NEW.status = ANY (approver_states)
       AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM NEW.status) THEN
      RAISE EXCEPTION 'only an editor or admin may submit, approve or decline a CCE application';
    END IF;
    IF TG_OP = 'UPDATE' THEN
      NEW.submitted_at = OLD.submitted_at;
      NEW.jotform_reference = OLD.jotform_reference;
      NEW.submitted_by = OLD.submitted_by;
      NEW.decision_at = OLD.decision_at;
      NEW.approved_cc_hours = OLD.approved_cc_hours;
      NEW.approved_rd_hours = OLD.approved_rd_hours;
      NEW.decision_notes = OLD.decision_notes;
    ELSE
      NEW.submitted_at = NULL;
      NEW.jotform_reference = NULL;
      NEW.submitted_by = NULL;
      NEW.decision_at = NULL;
      NEW.approved_cc_hours = NULL;
      NEW.approved_rd_hours = NULL;
      NEW.decision_notes = NULL;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.tg_event_cce_sync_public()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    UPDATE public.events
       SET cce_approved_cc_hours = NULL, cce_approved_rd_hours = NULL
     WHERE id = OLD.event_id;
    RETURN OLD;
  END IF;

  IF NEW.status = 'approved' THEN
    UPDATE public.events
       SET cce_approved_cc_hours = NEW.approved_cc_hours,
           cce_approved_rd_hours = NEW.approved_rd_hours
     WHERE id = NEW.event_id;
  ELSE
    UPDATE public.events
       SET cce_approved_cc_hours = NULL, cce_approved_rd_hours = NULL
     WHERE id = NEW.event_id;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.tg_event_recaps_content_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.headline is distinct from old.headline
     or new.body is distinct from old.body then
    new.content_updated_at = now();
  end if;
  if new.status = 'published' and old.status is distinct from 'published' then
    new.published_at = coalesce(new.published_at, now());
  end if;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.tg_event_registration_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  ev public.events%ROWTYPE;
  tier public.event_ticket_tiers%ROWTYPE;
  dc public.event_discount_codes%ROWTYPE;
  discount integer := 0;
  used integer;
  taken integer;
  trusted boolean := coalesce(auth.role(), current_user) = 'service_role';
  manager boolean := false;
BEGIN
  NEW.email = lower(btrim(NEW.email));
  NEW.updated_at = now();

  IF auth.uid() IS NOT NULL THEN
    manager := private.event_is_managed_by(NEW.event_id, auth.uid());
  END IF;

  IF TG_OP = 'UPDATE' AND NOT trusted AND NOT manager THEN
    NEW.event_id = OLD.event_id;
    NEW.user_id = OLD.user_id;
    NEW.tier_id = OLD.tier_id;
    NEW.payment_status = OLD.payment_status;
    NEW.amount_cents = OLD.amount_cents;
    NEW.currency = OLD.currency;
    NEW.stripe_session_id = OLD.stripe_session_id;
    NEW.hold_expires_at = OLD.hold_expires_at;
    NEW.discount_code_id = OLD.discount_code_id;
    NEW.checked_in_at = OLD.checked_in_at;
    NEW.checked_in_by = OLD.checked_in_by;
  END IF;

  IF TG_OP = 'UPDATE' AND NOT trusted THEN
    NEW.payment_environment = OLD.payment_environment;
    NEW.refund_status = OLD.refund_status;
    NEW.refund_amount_cents = OLD.refund_amount_cents;
    NEW.stripe_refund_id = OLD.stripe_refund_id;
    NEW.refunded_at = OLD.refunded_at;
    NEW.refund_error = OLD.refund_error;
    NEW.cancellation_status = OLD.cancellation_status;
    NEW.cancellation_sent_at = OLD.cancellation_sent_at;
    NEW.cancellation_error = OLD.cancellation_error;
    NEW.discount_code_text = OLD.discount_code_text;
    NEW.discount_type = OLD.discount_type;
    NEW.discount_value = OLD.discount_value;
    NEW.discount_amount_cents = OLD.discount_amount_cents;
    NEW.check_in_token = OLD.check_in_token;
    NEW.created_by_staff = OLD.created_by_staff;
    NEW.reminder_7d_sent_at = OLD.reminder_7d_sent_at;
    NEW.reminder_1d_sent_at = OLD.reminder_1d_sent_at;
    -- How an attendance was recorded is decided by the check-in routines only.
    NEW.checked_in_source = OLD.checked_in_source;
    NEW.checked_in_session_id = OLD.checked_in_session_id;
  END IF;

  IF TG_OP = 'UPDATE'
     AND NEW.payment_status = 'paid'
     AND OLD.payment_status IS DISTINCT FROM 'paid'
     AND auth.uid() IS NOT NULL THEN
    RAISE EXCEPTION 'payment status can only be set by the payment confirmation path';
  END IF;

  IF TG_OP = 'INSERT' AND NOT trusted THEN
    NEW.checked_in_at = NULL;
    NEW.checked_in_by = NULL;
    NEW.checked_in_source = NULL;
    NEW.checked_in_session_id = NULL;
    NEW.created_by_staff = NULL;
    NEW.reminder_7d_sent_at = NULL;
    NEW.reminder_1d_sent_at = NULL;
    NEW.amount_cents = 0;
    NEW.currency = 'CHF';
    NEW.discount_code_text = NULL;
    NEW.discount_type = NULL;
    NEW.discount_value = NULL;
    NEW.discount_amount_cents = 0;
    NEW.stripe_session_id = NULL;
    NEW.payment_environment = NULL;
    NEW.refund_status = 'none';
    NEW.refund_amount_cents = 0;
    NEW.stripe_refund_id = NULL;
    NEW.refunded_at = NULL;
    NEW.refund_error = NULL;
    IF NEW.payment_status = 'paid' AND NOT manager THEN
      RAISE EXCEPTION 'payment status can only be set by the payment confirmation path';
    END IF;
  END IF;

  IF NEW.status = 'cancelled' THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.status = 'confirmed' AND NEW.status = 'confirmed' THEN
    RETURN NEW;
  END IF;

  SELECT * INTO ev FROM public.events WHERE id = NEW.event_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'event not found';
  END IF;

  IF ev.status <> 'published' THEN
    RAISE EXCEPTION 'event is not open for registration';
  END IF;
  IF ev.registration_mode = 'none' THEN
    RAISE EXCEPTION 'this event does not take registrations';
  END IF;
  IF ev.registration_opens_at IS NOT NULL AND now() < ev.registration_opens_at THEN
    RAISE EXCEPTION 'registration has not opened yet';
  END IF;
  IF ev.registration_closes_at IS NOT NULL AND now() > ev.registration_closes_at THEN
    RAISE EXCEPTION 'registration has closed';
  END IF;

  IF ev.registration_mode = 'rsvp_members'
     AND NOT ev.guest_registration_allowed
     AND NOT trusted THEN
    IF NEW.user_id IS NULL
       OR NOT EXISTS (
         SELECT 1 FROM public.members m
          WHERE m.auth_user_id = NEW.user_id
            AND m.activity_state = 'active'
       ) THEN
      RAISE EXCEPTION 'this event is open to active members only';
    END IF;
  END IF;

  IF ev.registration_mode = 'rsvp_tickets' THEN
    IF NEW.tier_id IS NULL THEN
      RAISE EXCEPTION 'a ticket tier must be selected for this event';
    END IF;
    SELECT * INTO tier FROM public.event_ticket_tiers WHERE id = NEW.tier_id FOR UPDATE;
    IF NOT FOUND OR tier.event_id <> NEW.event_id OR NOT tier.is_active THEN
      RAISE EXCEPTION 'ticket tier is not available for this event';
    END IF;

    NEW.amount_cents = tier.price_cents;
    NEW.currency = tier.currency;

    IF NEW.discount_code_id IS NOT NULL THEN
      SELECT * INTO dc FROM public.event_discount_codes
        WHERE id = NEW.discount_code_id FOR UPDATE;
      IF NOT FOUND
         OR dc.event_id <> NEW.event_id
         OR dc.is_archived
         OR NOT dc.is_active
         OR (dc.starts_at IS NOT NULL AND now() < dc.starts_at)
         OR (dc.expires_at IS NOT NULL AND now() > dc.expires_at)
         OR (coalesce(array_length(dc.tier_ids, 1), 0) > 0 AND NOT (NEW.tier_id = ANY (dc.tier_ids)))
      THEN
        RAISE EXCEPTION 'discount code is not valid for this registration';
      END IF;

      IF dc.member_only AND NOT trusted THEN
        IF NEW.user_id IS NULL
           OR NOT EXISTS (
             SELECT 1 FROM public.members m
              WHERE m.auth_user_id = NEW.user_id
                AND m.activity_state = 'active'
           ) THEN
          RAISE EXCEPTION 'discount code is available to active members only';
        END IF;
      END IF;

      IF dc.max_uses IS NOT NULL THEN
        SELECT count(*) INTO used
        FROM public.event_registrations r
        WHERE r.discount_code_id = dc.id
          AND (TG_OP = 'INSERT' OR r.id <> NEW.id)
          AND r.status = 'confirmed'
          AND (
            r.payment_status IN ('not_required', 'paid')
            OR (r.payment_status = 'pending'
                AND (r.hold_expires_at IS NULL OR r.hold_expires_at > now()))
          );
        IF used >= dc.max_uses THEN
          RAISE EXCEPTION 'discount code has been fully used';
        END IF;
      END IF;

      IF dc.discount_type = 'percentage' THEN
        discount := floor(tier.price_cents * least(dc.discount_value, 100) / 100.0);
      ELSE
        discount := least(dc.discount_value, tier.price_cents);
      END IF;
      discount := greatest(discount, 0);

      NEW.discount_code_text = dc.code;
      NEW.discount_type = dc.discount_type;
      NEW.discount_value = dc.discount_value;
      NEW.discount_amount_cents = discount;
      NEW.amount_cents = greatest(tier.price_cents - discount, 0);
    END IF;

    IF tier.capacity IS NOT NULL THEN
      SELECT count(*) INTO taken
      FROM public.event_registrations r
      WHERE r.tier_id = tier.id
        AND (TG_OP = 'INSERT' OR r.id <> NEW.id)
        AND r.status = 'confirmed'
        AND (
          r.payment_status IN ('not_required', 'paid')
          OR (r.payment_status = 'pending'
              AND (r.hold_expires_at IS NULL OR r.hold_expires_at > now()))
        );
      IF taken >= tier.capacity THEN
        RAISE EXCEPTION 'ticket tier is full';
      END IF;
    END IF;
  END IF;

  IF ev.capacity IS NOT NULL THEN
    SELECT count(*) INTO taken
    FROM public.event_registrations r
    WHERE r.event_id = NEW.event_id
      AND (TG_OP = 'INSERT' OR r.id <> NEW.id)
      AND r.status = 'confirmed'
      AND (
        r.payment_status IN ('not_required', 'paid')
        OR (r.payment_status = 'pending'
            AND (r.hold_expires_at IS NULL OR r.hold_expires_at > now()))
      );
    IF taken >= ev.capacity THEN
      RAISE EXCEPTION 'event is full';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.tg_events_publish_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status = 'published' THEN
    IF coalesce(btrim(NEW.title), '') = '' THEN
      RAISE EXCEPTION 'a published event needs a title';
    END IF;
    IF coalesce(btrim(NEW.slug), '') = '' THEN
      RAISE EXCEPTION 'a published event needs a slug';
    END IF;
    IF NEW.starts_at IS NULL THEN
      RAISE EXCEPTION 'a published event needs a start time';
    END IF;
    NEW.published_at = coalesce(NEW.published_at, now());
  END IF;
  IF NEW.ends_at IS NOT NULL AND NEW.ends_at < NEW.starts_at THEN
    RAISE EXCEPTION 'an event cannot end before it starts';
  END IF;
  IF NEW.registration_closes_at IS NOT NULL
     AND NEW.registration_opens_at IS NOT NULL
     AND NEW.registration_closes_at < NEW.registration_opens_at THEN
    RAISE EXCEPTION 'registration cannot close before it opens';
  END IF;
  RETURN NEW;
END; $function$
;

CREATE OR REPLACE FUNCTION public.tg_events_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.updated_at = now();
  IF TG_OP = 'UPDATE' AND (
       NEW.title IS DISTINCT FROM OLD.title
    OR NEW.summary IS DISTINCT FROM OLD.summary
    OR NEW.description IS DISTINCT FROM OLD.description
  ) THEN
    NEW.content_updated_at = now();
  END IF;
  RETURN NEW;
END; $function$
;

CREATE OR REPLACE FUNCTION public.tg_guest_pass_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  ev public.events%ROWTYPE;
  trusted boolean := coalesce(auth.role(), current_user) = 'service_role';
  staff boolean := auth.uid() IS NOT NULL AND private.is_membership_staff(auth.uid());
BEGIN
  NEW.updated_at = now();

  IF TG_OP = 'INSERT' THEN
    NEW.guest_email = lower(btrim(NEW.guest_email));

    IF NOT trusted AND NOT staff THEN
      -- A member may only ever name a guest; the guest completes the profile.
      NEW.status = 'invited';
      NEW.decision_by = NULL;
      NEW.decision_at = NULL;
      NEW.decision_note = NULL;
      NEW.registration_id = NULL;
      NEW.follow_up_status = 'none';
      NEW.follow_up_note = NULL;
      NEW.converted_member_id = NULL;
      NEW.follow_up_consent = false;
      NEW.follow_up_consent_at = NULL;
      NEW.guest_completed_at = NULL;
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM public.members m
       WHERE m.id = NEW.inviting_member_id
         AND m.activity_state = 'active'
    ) THEN
      RAISE EXCEPTION 'guest pass: the inviting member is not an active member';
    END IF;

    SELECT * INTO ev FROM public.events WHERE id = NEW.event_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'guest pass: event not found';
    END IF;
    IF NOT ev.guest_passes_allowed THEN
      RAISE EXCEPTION 'guest pass: this event does not offer guest passes';
    END IF;
    IF ev.registration_mode = 'none' THEN
      RAISE EXCEPTION 'guest pass: this event does not take registrations';
    END IF;

    -- `invited` and `pending` do not consume the pass; only a granted seat does.
    IF EXISTS (
      SELECT 1 FROM public.guest_passes g
       WHERE lower(g.guest_email) = NEW.guest_email
         AND g.status IN ('approved', 'registered', 'attended')
    ) THEN
      RAISE EXCEPTION 'guest pass: this guest has already used a guest pass';
    END IF;

    IF EXISTS (
      SELECT 1 FROM public.guest_passes g
       WHERE g.event_id = NEW.event_id
         AND lower(g.guest_email) = NEW.guest_email
    ) THEN
      RAISE EXCEPTION 'guest pass: this guest already has a request for this event';
    END IF;

    RETURN NEW;
  END IF;

  -- UPDATE: only staff or the trusted server path may move the decision, the
  -- status, or the consent record. The guest's own completion runs through the
  -- trusted server path, never through a browser client.
  IF NOT trusted AND NOT staff THEN
    NEW.status = OLD.status;
    NEW.decision_by = OLD.decision_by;
    NEW.decision_at = OLD.decision_at;
    NEW.decision_note = OLD.decision_note;
    NEW.registration_id = OLD.registration_id;
    NEW.follow_up_status = OLD.follow_up_status;
    NEW.follow_up_note = OLD.follow_up_note;
    NEW.converted_member_id = OLD.converted_member_id;
    NEW.invite_token_hash = OLD.invite_token_hash;
    NEW.invited_at = OLD.invited_at;
    NEW.guest_completed_at = OLD.guest_completed_at;
    NEW.follow_up_consent = OLD.follow_up_consent;
    NEW.follow_up_consent_at = OLD.follow_up_consent_at;
    NEW.privacy_notice_version = OLD.privacy_notice_version;
  END IF;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.tg_guide_sections_touch_guide()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update public.guides set content_updated_at = now()
  where id = coalesce(new.guide_id, old.guide_id);
  return coalesce(new, old);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.tg_guides_content_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.title is distinct from old.title
     or new.summary is distinct from old.summary
     or new.eyebrow is distinct from old.eyebrow
     or new.intro is distinct from old.intro
     or new.footnote is distinct from old.footnote then
    new.content_updated_at := now();
  end if;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.tg_integration_config_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.updated_at = now();
  -- TEST mode can never send member email or open account claim.
  IF NEW.mode = 'test' THEN
    NEW.emails_suppressed = true;
    NEW.account_claim_enabled = false;
  END IF;
  -- Claim only opens after a recorded LIVE cutover.
  IF NEW.account_claim_enabled AND (NEW.mode <> 'live' OR NEW.cutover_completed_at IS NULL) THEN
    RAISE EXCEPTION 'account_claim_enabled requires live mode and a completed cutover';
  END IF;
  -- Mode is a one-way door.
  IF TG_OP = 'UPDATE' AND OLD.mode = 'live' AND NEW.mode = 'test' THEN
    RAISE EXCEPTION 'cannot revert integration mode from live to test';
  END IF;
  RETURN NEW;
END; $function$
;

CREATE OR REPLACE FUNCTION public.tg_member_profile_content_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.tagline IS DISTINCT FROM OLD.tagline
     OR NEW.description IS DISTINCT FROM OLD.description
     OR NEW.approach IS DISTINCT FROM OLD.approach
     OR NEW.qualifications IS DISTINCT FROM OLD.qualifications
     OR NEW.fees_note IS DISTINCT FROM OLD.fees_note
     OR NEW.session_length_note IS DISTINCT FROM OLD.session_length_note
     OR NEW.availability_note IS DISTINCT FROM OLD.availability_note
     OR NEW.response_time_note IS DISTINCT FROM OLD.response_time_note
     OR NEW.testimonial_quote IS DISTINCT FROM OLD.testimonial_quote
     OR NEW.testimonial_attribution IS DISTINCT FROM OLD.testimonial_attribution
     OR NEW.team_bio IS DISTINCT FROM OLD.team_bio
     OR NEW.primary_locale IS DISTINCT FROM OLD.primary_locale THEN
    NEW.content_updated_at = now();
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.tg_newsletters_publish_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  uid uuid := auth.uid();
  is_admin boolean := private.has_role(auth.uid(), 'admin');
BEGIN
  IF NEW.status IN ('published', 'scheduled')
     AND NEW.status IS DISTINCT FROM OLD.status THEN
    IF NOT is_admin AND NOT private.is_article_publisher(uid) THEN
      RAISE EXCEPTION 'only a publisher may publish a newsletter';
    END IF;
    IF NOT is_admin AND NEW.created_by IS NOT NULL AND NEW.created_by = uid THEN
      RAISE EXCEPTION 'the creator of a newsletter cannot publish it; another publisher must review it';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.tg_op_projects_content_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.name IS DISTINCT FROM OLD.name
     OR NEW.description IS DISTINCT FROM OLD.description
     OR NEW.cadence_note IS DISTINCT FROM OLD.cadence_note THEN
    NEW.content_updated_at = now();
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.tg_op_projects_single_featured_community()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.is_featured_community AND NOT NEW.is_community THEN
    NEW.is_featured_community = false;
  END IF;
  IF NEW.is_featured_community THEN
    UPDATE public.op_projects
      SET is_featured_community = false
      WHERE is_featured_community = true
        AND id <> NEW.id;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.tg_op_projects_sync_cadence()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v public.cf_cadences%ROWTYPE;
BEGIN
  IF NEW.cadence_slug IS NULL THEN
    NEW.cadence_note := NULL;
    NEW.cadence_note_de := NULL;
    NEW.cadence_note_fr := NULL;
    NEW.cadence_note_it := NULL;
  ELSE
    SELECT * INTO v FROM public.cf_cadences WHERE slug = NEW.cadence_slug;
    IF FOUND THEN
      NEW.cadence_note := v.name;
      NEW.cadence_note_de := v.name_de;
      NEW.cadence_note_fr := v.name_fr;
      NEW.cadence_note_it := v.name_it;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.tg_profiles_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN NEW.updated_at = now(); RETURN NEW; END; $function$
;

CREATE OR REPLACE FUNCTION public.tg_registration_attendance_undone()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF OLD.checked_in_at IS NOT NULL AND NEW.checked_in_at IS NULL THEN
    UPDATE public.event_certificates
       SET status = 'revoked', revoked_at = now(), revoke_reason = 'attendance_undone'
     WHERE registration_id = NEW.id AND status = 'issued';

    UPDATE public.event_cce_awards
       SET status = 'revoked', revoked_at = now()
     WHERE registration_id = NEW.id AND status = 'awarded';
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.tg_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.tg_user_roles_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.role_grants (user_id, role, action, actor_user_id)
    VALUES (NEW.user_id, NEW.role, 'granted', auth.uid());
    RETURN NEW;
  ELSE
    INSERT INTO public.role_grants (user_id, role, action, actor_user_id)
    VALUES (OLD.user_id, OLD.role, 'revoked', auth.uid());
    RETURN OLD;
  END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.tg_user_roles_protect_last_admin()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  remaining integer;
BEGIN
  IF OLD.role <> 'admin'::public.app_role THEN
    RETURN OLD;
  END IF;

  IF auth.uid() IS NOT NULL AND OLD.user_id = auth.uid() THEN
    RAISE EXCEPTION 'you cannot remove your own Super Admin access';
  END IF;

  SELECT count(*) INTO remaining
    FROM public.user_roles
   WHERE role = 'admin'::public.app_role;
  IF remaining <= 1 THEN
    RAISE EXCEPTION 'the last Super Admin cannot be removed';
  END IF;

  RETURN OLD;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.undo_check_in(_registration_id uuid, _actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  uid uuid := _actor;
  ev uuid;
BEGIN
  IF uid IS NULL OR NOT (private.has_role(uid, 'admin') OR private.has_role(uid, 'editor')) THEN
    RAISE EXCEPTION 'not authorised';
  END IF;
  SELECT event_id INTO ev FROM public.event_registrations WHERE id = _registration_id;
  IF ev IS NULL THEN
    RETURN jsonb_build_object('outcome', 'not_found');
  END IF;
  UPDATE public.event_registrations
     SET checked_in_at = NULL, checked_in_by = NULL
   WHERE id = _registration_id;
  RETURN jsonb_build_object('outcome', 'undone');
END;
$function$
;

