create or replace view public.coach_directory_public with (security_invoker=on) as
 SELECT p.id AS profile_id,
    m.id AS member_id,
    m.full_name,
    m.city,
    m.country,
    m.organisation,
    upper(m.credential_slug) AS credential_slug,
    m.credential_awarded_on,
    p.tagline,
    p.description,
    p.website_url,
    p.linkedin_url,
    p.profile_image_path,
    p.availability_slug,
    p.coaching_available,
    p.mentor_accredited,
    p.mentoring_available,
    p.supervision_accredited,
    p.supervision_available,
    p.booking_url,
    p.response_time_note,
    p.approach,
    p.qualifications,
    p.experience_band,
    p.session_length_note,
    p.fees_note,
    p.availability_note,
    p.testimonial_quote,
    p.testimonial_attribution,
    p.primary_locale,
    COALESCE(( SELECT jsonb_object_agg(t.locale, jsonb_build_object('tagline', t.tagline, 'description', t.description, 'approach', t.approach, 'qualifications', t.qualifications, 'fees_note', t.fees_note, 'session_length_note', t.session_length_note, 'availability_note', t.availability_note, 'response_time_note', t.response_time_note, 'testimonial_quote', t.testimonial_quote, 'testimonial_attribution', t.testimonial_attribution)) AS jsonb_object_agg
           FROM member_profile_translations t
          WHERE t.profile_id = p.id AND t.is_ready), '{}'::jsonb) AS translations,
    private.directory_contact_email(p.id) AS contact_email,
    array_remove(ARRAY[
        CASE
            WHEN p.coaching_available THEN 'coaching'::text
            ELSE NULL::text
        END,
        CASE
            WHEN p.mentoring_available THEN 'mentoring'::text
            ELSE NULL::text
        END,
        CASE
            WHEN p.supervision_available THEN 'supervision'::text
            ELSE NULL::text
        END], NULL::text) AS services,
    COALESCE(( SELECT array_agg(r.slug ORDER BY r.sort_order) AS array_agg
           FROM member_profile_regions mpr
             JOIN cf_regions r ON r.id = mpr.region_id
          WHERE mpr.profile_id = p.id), '{}'::text[]) AS region_slugs,
    COALESCE(( SELECT array_agg(l.slug ORDER BY l.sort_order) AS array_agg
           FROM member_profile_languages mpl
             JOIN cf_languages l ON l.id = mpl.language_id
          WHERE mpl.profile_id = p.id), '{}'::text[]) AS language_slugs,
    COALESCE(( SELECT array_agg(s.slug ORDER BY s.sort_order) AS array_agg
           FROM member_profile_specialisations mps
             JOIN cf_specialisations s ON s.id = mps.specialisation_id
          WHERE mps.profile_id = p.id), '{}'::text[]) AS specialisation_slugs,
    COALESCE(( SELECT array_agg(f.slug ORDER BY f.sort_order) AS array_agg
           FROM member_profile_formats mpf
             JOIN cf_formats f ON f.id = mpf.format_id
          WHERE mpf.profile_id = p.id), '{}'::text[]) AS format_slugs,
    COALESCE(( SELECT array_agg(ct.slug ORDER BY ct.sort_order) AS array_agg
           FROM member_profile_client_types mpc
             JOIN cf_client_types ct ON ct.id = mpc.client_type_id
          WHERE mpc.profile_id = p.id), '{}'::text[]) AS client_type_slugs,
    member_is_active(m.activity_state) AS is_active_member,
    member_has_directory_credential(m.credential_slug, m.credential_expires_on) AS has_directory_credential,
    true AS is_directory_eligible,
    true AS is_directory_visible,
    p.updated_at
   FROM member_directory_profiles p
     JOIN members m ON m.id = p.member_id
  WHERE p.visibility = 'published'::member_visibility AND (member_is_active(m.activity_state) OR directory_allows_non_credentialed() AND m.activity_state = 'grace'::member_activity_state) AND (member_has_directory_credential(m.credential_slug, m.credential_expires_on) OR directory_allows_non_credentialed());

create or replace view public.event_form_questions_public with (security_invoker=true) as
 SELECT q.id,
    q.form_id,
    f.event_id,
    q.question_key,
    q.qtype,
    q.label,
    q.label_de,
    q.label_fr,
    q.label_it,
    q.help_text,
    q.help_text_de,
    q.help_text_fr,
    q.help_text_it,
    q.options,
    q.options_de,
    q.options_fr,
    q.options_it,
    q.rating_max,
    q.scale_low_label,
    q.scale_low_label_de,
    q.scale_low_label_fr,
    q.scale_low_label_it,
    q.scale_high_label,
    q.scale_high_label_de,
    q.scale_high_label_fr,
    q.scale_high_label_it,
    q.is_required,
    q.sort_order,
    q.condition_question_id,
    q.condition_value
   FROM event_form_questions q
     JOIN event_forms f ON f.id = q.form_id
     JOIN events e ON e.id = f.event_id
  WHERE f.kind = 'registration'::text AND f.is_active AND e.status = 'published'::event_status;

create or replace view public.event_forms_public with (security_invoker=on) as
 SELECT f.id,
    f.event_id,
    f.kind,
    f.thank_you,
    f.thank_you_de,
    f.thank_you_fr,
    f.thank_you_it
   FROM event_forms f
     JOIN events e ON e.id = f.event_id
  WHERE f.kind = 'registration'::text AND f.is_active AND e.status = 'published'::event_status;

create or replace view public.event_ticket_tiers_public with (security_invoker=on) as
 SELECT t.id,
    t.event_id,
    t.name,
    t.name_de,
    t.name_fr,
    t.name_it,
    t.description,
    t.description_de,
    t.description_fr,
    t.description_it,
    t.price_cents,
    t.currency,
    t.capacity,
    t.segment,
    t.sort_order,
        CASE
            WHEN t.capacity IS NULL THEN NULL::integer
            ELSE GREATEST(t.capacity - private.event_tier_taken_count(t.id), 0)
        END AS seats_remaining,
    t.capacity IS NOT NULL AND private.event_tier_taken_count(t.id) >= t.capacity AS is_sold_out
   FROM event_ticket_tiers t
     JOIN events e ON e.id = t.event_id
  WHERE t.is_active AND e.status = 'published'::event_status;

create or replace view public.events_public with (security_invoker=on) as
 SELECT e.id,
    e.slug,
    e.title,
    e.summary,
    e.description,
    e.language,
    e.image_url,
    e.image_credit_name,
    e.image_credit_url,
    e.starts_at,
    e.ends_at,
    e.timezone,
    e.location_mode,
    e.venue_name,
    e.city,
    e.online_url,
    e.is_featured,
    e.is_internal,
    e.registration_mode,
    e.capacity,
    e.guest_registration_allowed,
    e.registration_opens_at,
    e.registration_closes_at,
    private.event_confirmed_count(e.id) AS registration_count,
        CASE
            WHEN e.capacity IS NULL THEN NULL::integer
            ELSE GREATEST(e.capacity - private.event_confirmed_count(e.id), 0)
        END AS seats_remaining,
    e.capacity IS NOT NULL AND private.event_confirmed_count(e.id) >= e.capacity AS is_full,
    e.registration_mode <> 'none'::event_registration_mode AND (e.registration_opens_at IS NULL OR now() >= e.registration_opens_at) AND (e.registration_closes_at IS NULL OR now() <= e.registration_closes_at) AND (e.capacity IS NULL OR private.event_confirmed_count(e.id) < e.capacity) AS registration_open,
    c.slug AS category_slug,
    c.name AS category_name,
    r.slug AS region_slug,
    r.name AS region_name,
    e.published_at,
    e.updated_at,
    e.map_location,
    com.id AS community_id,
    com.slug AS community_slug,
    com.name AS community_name,
    e.hero_marks,
    e.cce_approved_cc_hours,
    e.cce_approved_rd_hours,
    e.guest_passes_allowed,
    e.tickets_enabled
   FROM events e
     LEFT JOIN cf_event_categories c ON c.id = e.category_id
     LEFT JOIN cf_regions r ON r.id = e.region_id
     LEFT JOIN op_projects com ON com.id = e.community_id AND com.is_community
  WHERE e.status = 'published'::event_status;

create or replace view public.team_directory_public with (security_invoker=on) as
 SELECT profile_id,
    member_id,
    full_name,
    profile_image_path,
    team_bio,
    primary_locale,
    linkedin_url,
    contact_email,
    public_coach_profile_id,
    translations,
    assignments,
    primary_sort_order
   FROM private.team_directory_rows() team_directory_rows(profile_id, member_id, full_name, profile_image_path, team_bio, primary_locale, linkedin_url, contact_email, public_coach_profile_id, translations, assignments, primary_sort_order);

create or replace view public.team_projects_public with (security_invoker=on) as
 SELECT id,
    slug,
    name,
    name_de,
    name_fr,
    name_it,
    sort_order,
    is_community,
    is_featured_community,
    description,
    description_de,
    description_fr,
    description_it,
    cadence_note,
    cadence_note_de,
    cadence_note_fr,
    cadence_note_it,
    public_contact_email AS contact_email,
    signup_url,
    language_slugs,
    cover_image_url,
    cover_image_alt,
    image_source,
    image_credit_name,
    image_credit_url
   FROM op_projects
  WHERE is_active;

